SELECT LTRIM(RTRIM(REPLACE(A.KOD, '*', '.'))) AS ProductCode, COALESCE(NULLIF(LTRIM(RTRIM(A.BC)), ''), NULLIF(LTRIM(RTRIM(L.BARCOD)), '')) AS Barcode, CAST(ISNULL(A.PERSHKRIM, N'') AS nvarchar(255)) AS ProductName, CAST(ISNULL(S.StockQty, 0) AS decimal(18,3)) AS StockQty, CAST(ISNULL(A.CMSH, 0) AS decimal(18,4)) AS Price, CAST(ISNULL(A.KOSTMES, 0) AS decimal(18,4)) AS PurchasePriceWithVat, CAST(ISNULL(A.CMSH, 0) AS decimal(18,4)) AS SalePriceWithVat FROM dbo.ARTIKUJ AS A LEFT JOIN (SELECT KARTLLG, SUM(ISNULL(SASIH, 0) - ISNULL(SASID, 0)) AS StockQty FROM dbo.LEVIZJEHD WHERE KMAG = 'MQ' GROUP BY KARTLLG) AS S ON S.KARTLLG = A.KOD OUTER APPLY (SELECT TOP 1 BARCOD FROM dbo.LEVIZJEHD AS X WHERE X.KARTLLG = A.KOD AND ISNULL(X.BARCOD, '') <> '' ORDER BY X.DATEDOK DESC) AS L WHERE A.KOD IS NOT NULL AND LTRIM(RTRIM(A.KOD)) <> '' AND ISNULL(A.NOTACTIV, 0) = 0;
